-- Casos de éxito reales (41): entidades públicas atendidas, con monto bruto y sin año.
--
-- Cómo usarlo: aplicar antes la migración 20261015120000_proyecto_monto y luego pegar y ejecutar esto en el
-- SQL Editor de Supabase (o con psql). Es idempotente: si ya existe un proyecto de la marca con el mismo
-- cliente y monto, no lo duplica. Se cargan con esEjemplo = false (el asistente virtual los puede citar).
-- Después se gestionan desde Dashboard → Web → Proyectos (imagen, orden, visibilidad).
--
-- Marca: toma la primera cuyo nombre contenga "fptecnologi".

WITH m AS (
  SELECT id FROM "Marca" WHERE nombre ILIKE '%fptecnologi%' ORDER BY "createdAt" LIMIT 1
)
INSERT INTO "Proyecto"
  ("id","marcaId","titulo","departamento","imagenUrl","cliente","anio","monto","descripcion","alcance","orden","activo","esEjemplo","updatedAt")
SELECT gen_random_uuid()::text, m.id, v.titulo, v.dpto, v.img, v.cliente, NULL, v.monto, v.descripcion, v.alcance, 0, true, false, now()
FROM m,
